// BattleQuery builds a statement over battle: Battle() → Using(ctx, db) → chain → terminal().
type BattleQuery struct {
	binding orm.Binding
	q       *orm.Q
	keyFn   func(*BattleRow) orm.Key // KeyByFn: client-side keying of the root collection
}

// KeyByFn keys the root collection by a function of each row (relations key by keyBy<Col>).
func (q *BattleQuery) KeyByFn(fn func(*BattleRow) orm.Key) *BattleQuery { q.keyFn = fn; return q }

// Req exposes the underlying request (debugging, plan inspection).
func (q *BattleQuery) Req() *orm.Req { return q.q.Req }

// Battle starts a query over battle.
func Battle() *BattleQuery { return &BattleQuery{q: orm.NewQ(mustEngine(), "battle")} }

// Using selects the context and pool or transaction for this query.
func (q *BattleQuery) Using(ctx context.Context, ex orm.Exec) *BattleQuery {
	q.binding = orm.NewBinding(ctx, ex)
	return q
}

// AESStatus returns row counts by stored AES key version.
func (q *BattleQuery) AESStatus(keyring orm.AESKeyring) (orm.AESRotationStatus, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return orm.AESRotationStatus{}, err
	}
	return ex.DB().AESStatus(ctx, ex, orm.AESRotationSpec{Table: "battle", PrimaryKeys: []string{"seq"}, VersionColumn: "aes_key_version"}, keyring)
}

// RotateAES re-encrypts every pending AES row to the keyring current version.
func (q *BattleQuery) RotateAES(keyring orm.AESKeyring) (int, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return 0, err
	}
	return ex.DB().RotateAESRows(ctx, ex, orm.AESRotationSpec{
		Table: "battle", PrimaryKeys: []string{"seq"}, VersionColumn: "aes_key_version",
		BatchSize: 1000,
		Columns: []orm.AESRotationColumn{
			{Name: "aes_hex_email", Styles: []string{"aes", "hex"}},
			{Name: "aes_hex_phone", Styles: []string{"aes", "hex"}},
		},
	}, keyring)
}

// Using selects the context and pool or transaction for this loaded row.
func (r *BattleRow) Using(ctx context.Context, ex orm.Exec) *BattleRow {
	r.Binding = orm.NewBinding(ctx, ex)
	return r
}

