func collectBattle(rows *orm.Rows, keyFn func(*BattleRow) orm.Key) *orm.Collection[BattleRow] {
	c := orm.NewCollection[BattleRow](len(rows.Data))
	for _, vals := range rows.Data {
		r := scanBattle(vals, rows.Assemble, rows)
		if keyFn != nil {
			c.Put(keyFn(r), r)
			continue
		}
		key, ok := orm.KeyFromRow(vals, rows.Assemble.Key)
		if !ok {
			panic("assembly collection key contains null")
		}
		c.Put(key, r)
	}
	return c
}

func collectBattleDirect(rows []*BattleRow, keyFn func(*BattleRow) orm.Key) *orm.Collection[BattleRow] {
	c := orm.NewCollection[BattleRow](len(rows))
	for _, r := range rows {
		if keyFn != nil {
			c.Put(keyFn(r), r)
		} else {
			c.Put(orm.KeyFromValues([]any{r.Seq}), r)
		}
	}
	return c
}

