func (q *BattleQuery) Paginate(page, per int) (*orm.Page[BattleRow], error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	if per <= 0 {
		return nil, &ir.Error{Code: "IR_INVALID", Msg: "per must be positive"}
	}
	if page < 1 {
		page = 1
	}
	q.q.Req.IR.Kind = "paginate"
	q.q.Node.Limit = &ir.Limit{Offset: (page - 1) * per, Count: per}
	rows, total, err := orm.Paginate(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	pages := (total + int64(per) - 1) / int64(per)
	return &orm.Page[BattleRow]{Items: collectBattle(rows, q.keyFn), Total: total, Pages: pages, Current: int64(page), Per: int64(per)}, nil
}

func (q *BattleQuery) Insert() (*BattleRow, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "insert"
	id, _, err := orm.Write(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	return Battle().Using(ctx, ex).SeqEq(int64(id)).Get()
}

// Save updates when every primary-key column was assigned and inserts when none was assigned.
func (q *BattleQuery) Save() (*BattleRow, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	keys, ok, err := q.q.MoveKeysToWhere([]string{"seq"})
	if err != nil {
		return nil, err
	}
	if !ok {
		return q.Insert()
	}
	q.q.Req.IR.Kind = "update"
	if _, _, err := orm.Write(ctx, ex, q.q.Req); err != nil {
		return nil, err
	}
	return Battle().Using(ctx, ex).SeqEq(keys[0].(int64)).Get()
}

